    74→  ) {
    75→    level = "S";
    76→  }
    77→  if (
    78→    normalizedScore >= RANK_DOUBLE_A_VALUE &&
    79→    normalizedScore < RANK_A2_VALUE
    80→  ) {
    81→    level = "A++";
    82→  }
